briefCalls.responseText:
{
  "primitive": "intro_briefing",
  "topic": "Break apart numbers 16-19 into ten ones and some further ones using visual models",
  "subject": "General",
  "gradeLevel": "kindergarten",
  "estimatedTime": "15-20 minutes",
  "hook": {
    "type": "scenario",
    "content": "Imagine you have a giant pile of 17 shiny star stickers! If you want to share them easily, you can put 10 of them onto a special star card, and leave the leftover stars right beside it. Let us discover how big numbers are just hiding a ten inside them!",
    "visualTheme": "counting"
  },
  "bigIdea": {
    "statement": "Numbers from 16 to 19 are made of a group of ten ones and some extra ones.",
    "whyItMatters": "Knowing how numbers are built helps us count faster, do big kid math, and make sense of groups of things all around us in the real world."
  },
  "objectives": [
    {
      "id": "obj1",
      "text": "Count out ten objects to make a full group of ten and separate the leftover ones",
      "verb": "apply",
      "icon": "puzzle"
    },
    {
      "id": "obj2",
      "text": "Identify how many total items make up numbers sixteen through nineteen using visual models",
      "verb": "identify",
      "icon": "search"
    },
    {
      "id": "obj3",
      "text": "Explain that numbers 16-19 are composed of ten ones and extra ones",
      "verb": "explain",
      "icon": "lightbulb"
    }
  ],
  "prerequisites": {
    "shouldKnow": [
      "Count objects up to 20 with one-to-one correspondence",
      "Understand that a group of 10 can be called 'a ten'",
      "Recognize numbers 10 through 20"
    ],
    "quickCheck": {
      "question": "Can you count out 10 counters from your pile and touch each one as you count?",
      "answer": "Ten counters counted one by one",
      "hint": "Take them slowly, one at a time, until you reach your magic number ten!"
    }
  },
  "roadmap": [
    {
      "phase": "Explore",
      "description": "Look at big groups of pictures and find the hidden ten.",
      "activities": [
        "Spot the group of 10 objects in a picture",
        "Circle the ten items together"
      ]
    },
    {
      "phase": "Build",
      "description": "Make numbers 16, 17, 18, and 19 using physical or digital counters.",
      "activities": [
        "Place 10 items in a ten-frame or box",
        "Put the extra ones next to the box"
      ]
    },
    {
      "phase": "Share",
      "description": "Talk about how many total items we have made.",
      "activities": [
        "Say aloud '10 and 4 more makes 14' and practice for 16-19",
        "Show a friend your group of ten and extra ones"
      ]
    }
  ],
  "connections": {
    "buildingFrom": [
      "Counting numbers 1 through 20",
      "Making numbers 11 through 15 using a ten and some ones"
    ],
    "leadingTo": [
      "Understanding place value with tens and ones",
      "Adding and subtracting larger numbers in first grade"
    ],
    "realWorld": [
      "Counting 17 crayons where 10 are in a box and 7 are on the desk",
      "Counting blocks when building a tall tower with a base of ten"
    ]
  },
  "mindset": {
    "encouragement": "Sometimes splitting big numbers can feel tricky at first, but once you find your group of ten, the rest is super easy!",
    "growthTip": "Always count your group of ten first so you know it is complete before counting your extra ones."
  }
}
